from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1
        else:
            self.cache.move_to_end(key) # Mark as recently used
            return self.cache[key]

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.cache.move_to_end(key) # Mark as recently used
        elif len(self.cache) >= self.capacity:
            self.cache.popitem(last=False) # Remove the least recently used item
        self.cache[key] = value

    def __len__(self):
        return len(self.cache)

    def __contains__(self, key):
        return key in self.cache

    def keys(self):
        return list(self.cache.keys())

```
This revised implementation uses `collections.OrderedDict`, which simplifies LRU logic significantly. `OrderedDict` remembers the order entries were added. `move_to_end(key)` moves an existing key to the end (most recently used). `popitem(last=False)` removes and returns the first item added (least recently used).

